```json
{
  "title": "Streaming Error",
  "type": "object",
  "properties": {
    "status": {
      "type": "integer",
      "description": "HTTP status code",
      "minimum": 100,
      "maximum": 599
    },
    "message": {
      "type": "string",
      "description": "Error message",
      "minLength": 1
    },
    "resume_details": {
      "type": "object",
      "description": "Additional details about the resume attempt",
      "properties": {
        "checkpoint_cursor": {
          "type": "string",
          "description": "Cursor pointing to the last checkpoint in the stream",
          "minLength": 1
        },
        "resume_token": {
          "type": "string",
          "description": "Token representing the state of the stream at the point of the resume attempt",
          "minLength": 1
        }
      }
    }
  }
}
```

